function DreamAdventuresComponent:AddActivityHP(value)
    local dojo = self:GetDreamAdventuresDojo()
    if not dojo or not dojo.hpData then return end
    
    dojo.hpData.hp = checkInt(dojo.hpData.hp) + checkInt(value)
end

