---设置任务红点
function DreamAdventuresComponent:SetTaskTips(taskTips, taskType)
    taskType = checkNumber(taskType)
    local dojo = self:GetDreamAdventuresDojo()
    if taskType == 1 then
        dojo.taskTips = tonumber(taskTips)
    else
        dojo.achievementTips = tonumber(taskTips)
    end
end

---获取任务红点
function DreamAdventuresComponent:GetTaskTips(taskType)
    taskType = checkNumber(taskType)
    local dojo = self:GetDreamAdventuresDojo()
    if taskType == 1 then
        return tonumber(dojo.taskTips)
    else
        return checkNumber(dojo.achievementTips)
    end
end

